-- 0267_permissions_seed_actions_delta_029.sql
-- Why: Catalog delta for issue #153. blueprint-api and bureau-api routes had no
--   permission catalog entries, so requireCan could not gate them and no built-in
--   group granted anything for them. Every route now calls requireCan() with one of
--   these 29 hand-authored blueprint.* / bureau.* ids (scripts/generate-permission-
--   manifest.mjs HAND_AUTHORED). Generated by scripts/build-permission-delta.mjs.
--   Built-in group defaults follow in 0268_blueprint_bureau_builtin_group_defaults.sql,
--   which must run AFTER this file (it cross-joins these rows).
-- Client impact: additive only (29 new permission rows, no removals).
--   Re-running is safe; INSERT...ON CONFLICT is idempotent.

-- 29 new permission(s)
ON CONFLICT (id) DO UPDATE SET
    app = EXCLUDED.app,
    resource = EXCLUDED.resource,
    verb = EXCLUDED.verb,
    description = EXCLUDED.description,
    is_destructive = EXCLUDED.is_destructive,
    requires_confirmation = EXCLUDED.requires_confirmation,
    is_read = EXCLUDED.is_read,
    requires_superuser = EXCLUDED.requires_superuser;
